from pathlib import Path
import re

ROOT=Path('.')

def read(path): return (ROOT/path).read_text()
def write(path,text): (ROOT/path).write_text(text)
def rep(path,old,new,count=1):
    text=read(path)
    if old not in text: raise SystemExit(f'PATRON NO ENCONTRADO {path}: {old[:100]!r}')
    text=text.replace(old,new,count)
    write(path,text)
def sub(path,pattern,repl,count=1,flags=re.S):
    text=read(path)
    out,n=re.subn(pattern,repl,text,count=count,flags=flags)
    if n!=count: raise SystemExit(f'REGEX {path}: esperado {count}, obtenido {n}: {pattern[:100]}')
    write(path,out)

