emit_fn="""export async function emitInvoice(invoice,user){
  if(!navigator.onLine)throw new Error('PARA EMITIR UNA FACTURA DEBES TENER CONEXIÓN A INTERNET');
  const checked=validateInvoice(invoice);if(checked.errors.length)throw new Error(checked.errors.join(' · '));
  const invoiceId=invoice.id||uid('inv'),sid=invoice.seriesId||'FA';
  return runTransaction(db,async tx=>{
    await assertMonthOpenTx(tx,invoice.date);
    const iref=ref('invoices',invoiceId),existing=await tx.get(iref),sref=ref('series',sid),ss=await tx.get(sref);
    if(existing.exists()&&existing.data().status!=='draft')throw new Error('ESTA FACTURA YA FUE EMITIDA');
    const unique=[...new Set((checked.invoice.lines||[]).map(l=>l.productId).filter(Boolean))],productSnaps=new Map();
    for(const pid of unique)productSnaps.set(pid,await tx.get(ref('products',pid)));
    const lines=(checked.invoice.lines||[]).map(l=>{const ps=productSnaps.get(l.productId),p=ps?.exists()?ps.data():null;return{...l,buyPriceSnapshot:Number(l.buyPriceSnapshot??p?.buyPrice??0)}});
    const calc=calcInvoice({...checked.invoice,lines}),s=ss.exists()?ss.data():{prefix:sid,next:1,digits:5},next=Number(s.next||1),number=`${s.prefix||sid}-${String(next).padStart(Number(s.digits||5),'0')}`,stamp=now();
    const emitted={...calc,id:invoiceId,number,status:'issued',issuedAt:stamp,createdAt:existing.exists()?existing.data().createdAt||stamp:stamp,updatedAt:stamp,issuerSnapshot:invoice.issuerSnapshot||invoice.settingsSnapshot||null,clientSnapshot:invoice.clientSnapshot||null};
    tx.set(iref,emitted,{merge:false});tx.set(sref,{...s,id:sid,next:next+1,updatedAt:stamp},{merge:true});
    for(const line of emitted.lines){const qty=stockMovementQty(line);if(qty<=0)continue;const mid=uid('sm');tx.set(ref('stockMoves',mid),{id:mid,productId:line.productId,qty:-qty,type:'sale',location:invoice.stockLocation||'ALMACEN',sourceId:invoiceId,note:`FACTURA ${number}`,date:invoice.date,createdAt:stamp})}
    for(const orderId of invoice.sourceOrderIds||[])tx.set(ref('orders',orderId),{status:'invoiced',invoiceId,updatedAt:stamp},{merge:true});
    const docMap={quote:'quotes',proforma:'proformas',delivery:'deliveryNotes'};if(invoice.sourceDocument?.kind&&invoice.sourceDocument?.id&&docMap[invoice.sourceDocument.kind])tx.set(ref(docMap[invoice.sourceDocument.kind],invoice.sourceDocument.id),{invoiceId,status:'invoiced',updatedAt:stamp},{merge:true});
    if(Number(emitted.paid||0)>0){const pid=uid('pay');tx.set(ref('payments',pid),{id:pid,clientId:invoice.clientId,date:invoice.date,amount:Number(emitted.paid),method:invoice.paymentMethod||'efectivo',allocations:[{invoiceId,amount:Number(emitted.paid)}],createdAt:stamp})}
    const aid=uid('a');tx.set(ref('audit',aid),{id:aid,action:'INVOICE_ISSUE',entity:'invoices',entityId:invoiceId,number,userEmail:user?.email||'',userUid:user?.uid||'',at:stamp});return emitted;
  });
}
"""
sub('js/firebase.js',r'export async function emitInvoice\(invoice,user\)\{.*?\nexport async function recordPayment',emit_fn+'export async function recordPayment')

atomic_ops="""
export async function saveStockOperation(collectionName,record,moves=[],action='STOCK_OPERATION',user=null){
  const id=record.id||uid(collectionName.slice(0,3)),stamp=now(),batch=writeBatch(db);
  batch.set(ref(collectionName,id),{...record,id,updatedAt:stamp},{merge:false});
  for(const raw of moves){const mid=raw.id||uid('sm');batch.set(ref('stockMoves',mid),{...raw,id:mid,sourceId:raw.sourceId||id,createdAt:raw.createdAt||stamp},{merge:false})}
  if(user){const aid=uid('a');batch.set(ref('audit',aid),{id:aid,action,entity:collectionName,entityId:id,userEmail:user.email||'',userUid:user.uid||'',at:stamp})}
  await batch.commit();return id;
}
export async function reopenMonthClosure(month,user){if(!isOwner(user))throw new Error('SOLO EL PROPIETARIO PUEDE REABRIR UN MES');const id=`close_${month}`,snap=await getDoc(ref('closures',id));if(!snap.exists())throw new Error('EL MES NO ESTÁ CERRADO');const batch=writeBatch(db);batch.delete(ref('closures',id));const aid=uid('a');batch.set(ref('audit',aid),{id:aid,action:'MONTH_REOPEN',entity:'closures',entityId:id,userEmail:user.email||'',userUid:user.uid||'',at:now()});await batch.commit();}
"""
rep('js/firebase.js','export async function zeroAllStockCloud',atomic_ops+'\nexport async function zeroAllStockCloud')

